#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define NCGP 16   /* B panels per L2 column block (16*16 = 256 columns) */

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof(v)); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    if (mr == MR) {
        for (int i = 0; i < MR; i++) {
            __builtin_prefetch(c + (size_t)i * ldc, 1, 3);
            __builtin_prefetch(c + (size_t)i * ldc + NR - 1, 1, 3);
        }
    }

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b + 16 * k);
        v8 b1 = *(const v8 *)(b + 16 * k + 8);
        const float *ap = a + 6 * k;
        float a0 = ap[0], a1 = ap[1], a2 = ap[2], a3 = ap[3], a4 = ap[4], a5 = ap[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
    }

    v8 acc[6][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                    {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int i = 0; i < MR; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum) {
                stu(cp, ldu(cp) + acc[i][0]);
                stu(cp + 8, ldu(cp + 8) + acc[i][1]);
            } else {
                stu(cp, acc[i][0]);
                stu(cp + 8, acc[i][1]);
            }
        }
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++) {
            stu(&tmp[i][0], acc[i][0]);
            stu(&tmp[i][8], acc[i][1]);
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int rp = (n + MR - 1) / MR;   /* row panels */
    int cp = (n + NR - 1) / NR;   /* column panels */
    size_t szA = (size_t)rp * MR * KC;
    size_t szB = (size_t)cp * NR * KC;
    float *Abuf = (float *)alloc64(2 * szA * sizeof(float));
    float *Bbuf = (float *)alloc64(2 * szB * sizeof(float));

    #pragma omp parallel
    {
        int nt = omp_get_num_threads();
        int t = omp_get_thread_num();

        /* choose a tr x tc thread grid minimizing the largest tile */
        int tr = 1, tc = nt;
        long best = -1;
        for (int d = 1; d <= nt; d++) {
            if (nt % d) continue;
            int e = nt / d;
            long cost = (long)((rp + d - 1) / d) * ((cp + e - 1) / e);
            if (best < 0 || cost < best) { best = cost; tr = d; tc = e; }
        }
        int ti = t / tc, tj = t % tc;
        int r0 = (int)((long)rp * ti / tr), r1 = (int)((long)rp * (ti + 1) / tr);
        int c0 = (int)((long)cp * tj / tc), c1 = (int)((long)cp * (tj + 1) / tc);

        int parity = 0;
        for (int pc = 0; pc < n; pc += KC, parity ^= 1) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;
            float *Ap = Abuf + parity * szA;
            float *Bp = Bbuf + parity * szB;

            /* pack A[:, pc:pc+kc] into MR-row panels */
            #pragma omp for schedule(static) nowait
            for (int ip = 0; ip < rp; ip++) {
                float *dst = Ap + (size_t)ip * kc * MR;
                int i0 = ip * MR;
                int mr = n - i0 < MR ? n - i0 : MR;
                if (mr == MR) {
                    const float *s0 = A + (size_t)(i0 + 0) * n + pc;
                    const float *s1 = A + (size_t)(i0 + 1) * n + pc;
                    const float *s2 = A + (size_t)(i0 + 2) * n + pc;
                    const float *s3 = A + (size_t)(i0 + 3) * n + pc;
                    const float *s4 = A + (size_t)(i0 + 4) * n + pc;
                    const float *s5 = A + (size_t)(i0 + 5) * n + pc;
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                        d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                    }
                } else {
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        int ii = 0;
                        for (; ii < mr; ii++) d[ii] = A[(size_t)(i0 + ii) * n + pc + k];
                        for (; ii < MR; ii++) d[ii] = 0.0f;
                    }
                }
            }

            /* pack B[pc:pc+kc, :] into NR-wide panels */
            #pragma omp for schedule(static)
            for (int jp = 0; jp < cp; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                if (nr == NR) {
                    for (int k = 0; k < kc; k++)
                        memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
                } else {
                    for (int k = 0; k < kc; k++) {
                        const float *src = B + (size_t)(pc + k) * n + j0;
                        float *d = dst + k * NR;
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            /* compute this thread's fixed C block; the B-pack barrier of the
               next pc plus double buffering make a trailing barrier unnecessary */
            for (int jb = c0; jb < c1; jb += NCGP) {
                int je = jb + NCGP < c1 ? jb + NCGP : c1;
                for (int ip = r0; ip < r1; ip++) {
                    int i = ip * MR;
                    int mr = n - i < MR ? n - i : MR;
                    const float *ap = Ap + (size_t)ip * kc * MR;
                    float *crow = C + (size_t)i * n;
                    for (int jp = jb; jp < je; jp++) {
                        int j = jp * NR;
                        int nr = n - j < NR ? n - j : NR;
                        kernel(kc, ap, Bp + (size_t)jp * kc * NR, crow + j, n, mr, nr, accum);
                    }
                }
            }
        }
    }
    free(Abuf);
    free(Bbuf);
}
